(function(){
  function parsePath(p){
    var s=String(p||'').replace(/^\./,''); var parts=[],buf='',i=0;
    while(i<s.length){ var c=s[i];
      if(c==='.'){ if(buf)parts.push(buf); buf=''; i++; }
      else if(c==='['){ if(buf)parts.push(buf); buf=''; var j=s.indexOf(']',i); if(j<0){parts.push(s.slice(i));break;} parts.push(s.slice(i,j+1)); i=j+1; }
      else { buf+=c; i++; } }
    if(buf)parts.push(buf); return parts;
  }
  function walk(o,parts){
    var cur=o;
    for(var i=0;i<parts.length;i++){ var p=parts[i]; if(p==='')continue;
      var m=p.match(/^\[(\d+)\]$/); if(m) cur=cur[parseInt(m[1],10)]; else cur=cur[p];
      if(cur===undefined) return {error:'路径不存在'}; }
    return {value:cur};
  }
  function pretty(t){
    var v; try{ v=JSON.parse(t); }catch(e){ return {error:'JSON 解析失败: '+e.message}; }
    return {value:JSON.stringify(v,null,2)};
  }
  function get(t,path){
    var v; try{ v=JSON.parse(t); }catch(e){ return {error:'JSON 解析失败: '+e.message}; }
    var r=walk(v,parsePath(path)); if(r.error)return r;
    return {value: typeof r.value==='object'? JSON.stringify(r.value,null,2): String(r.value)};
  }
  var API={pretty:pretty,get:get,parsePath:parsePath};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__FxForge__=API;
})();
